function applyExactOfficialText(){
 const seeds=[...SUS26_1,...SUS26_2,...SUS26_3,...SUS26_SHORT,...SUS26_4], byNum=Object.fromEntries(seeds.map(q=>[q.number,q]));
 const starts=[1,4,7,10,13,16,19,22,25,28,31,34,37,40,43,46,49,52,55,58,61,64,67,70,73];
 starts.forEach(st=>{let src=SUS26_EXACT_CASES[st]||byNum[st]?.caseText;if(src)for(let n=st;n<st+3;n++)if(byNum[n])byNum[n].caseText=src});
 Object.entries(SUS26_EXACT_Q1_15).forEach(([n,v])=>{let q=byNum[n];if(q){q.prompt=v.prompt;q.alternatives=v.alternatives}});
 if(db&&db.bankQuestions){let changed=false;for(const seed of seeds){let q=db.bankQuestions.find(x=>x.id===seed.id);if(!q)continue;for(const k of ['caseText','prompt','alternatives'])if(seed[k]!=null&&JSON.stringify(q[k])!==JSON.stringify(seed[k])){q[k]=seed[k];changed=true}}return changed}
 return false
}
applyExactOfficialText();
// Reconcile SUS-BA 2024.1 against the definitive Strix answer key, including annulments.
// Retain every original attempt and selected alternative; repair grading and stored seed metadata.
function reconcileSUS241Definitive(){
 let changed=false;
 // Rebuild the FULL official exam from the original source on every local/cloud load.
 // A previously saved question may have the correct ID but a shifted stem or choices.
 const seeds=new Map(SUS241.map(q=>[q.id,q]));
 const officialFields=['number','exam','area','topic','type','caseText','prompt','alternatives','correctIndex','annulled','resolution'];
 const seen=new Set();
 for(const saved of db.bankQuestions||[]){
  const seed=seeds.get(saved.id);if(!seed)continue;
  seen.add(seed.id);
  for(const k of officialFields){
   if(JSON.stringify(saved[k])!==JSON.stringify(seed[k])){
    if(seed[k]===undefined)delete saved[k];else saved[k]=seed[k];
    changed=true;
   }
  }
 }
 for(const seed of SUS241){if(!seen.has(seed.id)){db.bankQuestions.push({...seed});changed=true}}
 // Correct previous grading without deleting attempts or changing selected answers.
 for(const attempt of db.bankAttempts||[]){
  const seed=seeds.get(attempt.questionId);if(!seed||seed.number>45)continue;
  const correct=seed.annulled?true:attempt.answer===seed.correctIndex;
  if(attempt.correct!==correct){attempt.correct=correct;attempt.correctedByDefinitive=true;changed=true}
 }
 return changed;
}
