let studyClock={route:null,started:Date.now(),lastFlush:Date.now(),lastWasVisible:!document.hidden};
const FM_SITE_STREAK_MINUTES=30;
function flushStudyTime(forceCloud=false){
 const t=Date.now(),ms=Math.max(0,t-studyClock.lastFlush),wasVisible=studyClock.lastWasVisible;
 studyClock.lastFlush=t;
 // A visibility-change flush may include the final foreground interval; background time never counts.
 const countable=!!currentUser&&wasVisible&&(!document.hidden||forceCloud);
 studyClock.lastWasVisible=!document.hidden;
 if(!currentUser||!countable||ms<=0)return;
 const key=day(),label=studyClock.route||route||'Geral';
 db.siteUsage=db.siteUsage||{};
 const before=Number(db.siteUsage[key])||0;
 db.siteUsage[key]=before+ms;
 db.studyTime=db.studyTime||{};
 db.studyTime[key]=db.studyTime[key]||{};
 if(ms>=15000)db.studyTime[key][label]=(db.studyTime[key][label]||0)+ms;
 db.updatedAt=t;
 try{localStorage.setItem(KEY,JSON.stringify(flashmedLocalPayload(db)))}catch(e){}
 const crossedThreshold=before<FM_SITE_STREAK_MINUTES*60000&&db.siteUsage[key]>=FM_SITE_STREAK_MINUTES*60000;
 if(cloud&&(forceCloud||crossedThreshold)){clearTimeout(cloudTimer);cloudTimer=setTimeout(syncUp,300)}
}
